#include <stdio.h>
/* ex04：磁盘访问时间三要素
 *   访问时间 Ta = 寻道时间 Ts + 旋转延迟 Tr + 传输时间 Tt
 *   平均旋转延迟 = 半圈时间 = (1/2) * (60/RPM) 秒
 *   传输时间 = 传输字节数 / 传输速率
 * 这道题每年都考，关键是「平均」二字：平均旋转延迟是半圈，不是一圈。*/
int main(void) {
    int rpm = 7200;              /* 转速 7200 r/min */
    double seek_ms = 8.0;        /* 平均寻道时间 */
    int sector = 512;            /* 每扇区 512B */
    int sectors_per_track = 400; /* 每道 400 扇区 */
    int read_sectors = 8;        /* 本次读 8 个扇区 = 4KB */

    double rot_ms = 60.0 / rpm * 1000.0;          /* 转一圈的毫秒数 */
    double avg_rot = rot_ms / 2.0;                /* 平均旋转延迟 = 半圈 */
    double track_bytes = (double)sector * sectors_per_track;
    double transfer_ms = (double)read_sectors * sector / track_bytes * rot_ms;

    printf("转速=%drpm -> 一圈 %.2fms，平均旋转延迟 %.2fms\n", rpm, rot_ms, avg_rot);
    printf("--------------------------------------------------\n");
    printf("寻道时间     = %.2f ms\n", seek_ms);
    printf("旋转延迟     = %.2f ms\n", avg_rot);
    printf("传输 4KB     = %.3f ms\n", transfer_ms);
    printf("--------------------------------------------------\n");
    printf("总访问时间   = %.2f ms\n", seek_ms + avg_rot + transfer_ms);
    printf("\n时间构成占比：寻道 %.0f%%，旋转 %.0f%%，传输 %.1f%%\n",
           100 * seek_ms / (seek_ms + avg_rot + transfer_ms),
           100 * avg_rot / (seek_ms + avg_rot + transfer_ms),
           100 * transfer_ms / (seek_ms + avg_rot + transfer_ms));
    printf("结论：机械盘上「传输」只占几个百分点——所以优化方向是「减少寻道次数」，\n");
    printf("      这就是磁盘调度算法的意义，也是 SSD 能碾压 HDD 的根本原因（没有寻道）。\n");
    return 0;
}
